// Generates responsive variants for every raster image under public/images so
// the custom next/image loader (lib/imageLoader.ts) can serve 640px, 1024px and 1280px
// files to phones and tablets instead of the 1200-2400px originals.
//
// Output files sit next to the source as `<name>.w640.webp`, `.w1024.webp` and `.w1280.webp`.
// They are build artefacts (gitignored) and are regenerated by `npm run prebuild`.
import { readdir, stat } from "node:fs/promises";
import path from "node:path";
import sharp from "sharp";

const root = path.join(process.cwd(), "public", "images");
const widths = [640, 1024, 1280];
const sourceExtensions = new Set([".webp", ".jpg", ".jpeg", ".png"]);
const variantPattern = /\.w(640|1024|1280)\.webp$/;

async function* walk(dir) {
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) yield* walk(full);
    else yield full;
  }
}

let generated = 0;
let skipped = 0;
let failed = 0;
const started = Date.now();

for await (const file of walk(root)) {
  const ext = path.extname(file).toLowerCase();
  if (!sourceExtensions.has(ext) || variantPattern.test(file)) continue;
  const base = file.slice(0, -ext.length);
  const sourceStat = await stat(file);
  for (const width of widths) {
    const target = `${base}.w${width}.webp`;
    try {
      const targetStat = await stat(target).catch(() => null);
      if (targetStat && targetStat.mtimeMs >= sourceStat.mtimeMs) {
        skipped += 1;
        continue;
      }
      await sharp(file)
        .rotate()
        .resize({ width, withoutEnlargement: true })
        .webp({ quality: 78, effort: 4 })
        .toFile(target);
      generated += 1;
    } catch (error) {
      failed += 1;
      console.error(`image variant failed: ${path.relative(process.cwd(), file)} @${width}: ${error.message}`);
    }
  }
}

console.log(
  `image variants: ${generated} generated, ${skipped} up to date, ${failed} failed in ${((Date.now() - started) / 1000).toFixed(1)}s`,
);
if (failed > 0) process.exit(1);
